// Small deterministic PRNG for replayable game simulation.
// A session seed must be generated by the server and stored with the session.
// Do not use this helper for security tokens, passwords, or cryptography.
const UINT32_RANGE = 0x1_0000_0000;
const ZERO_SEED_FALLBACK = 0x6d2b79f5;

export function normalizeSimulationSeed(seed) {
  if (!Number.isSafeInteger(seed) || seed < 0 || seed > 0xffff_ffff) {
    throw new RangeError("INVALID_SIMULATION_SEED");
  }
  return seed === 0 ? ZERO_SEED_FALLBACK : seed >>> 0;
}

export function createSeededRandom(seed) {
  let state = normalizeSimulationSeed(seed);

  function nextUint32() {
    // xorshift32: stable unsigned 32-bit operations in JS engines.
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    state >>>= 0;
    return state;
  }

  function nextFloat() {
    return nextUint32() / UINT32_RANGE;
  }

  function nextInt(min, max) {
    if (!Number.isSafeInteger(min) || !Number.isSafeInteger(max) || max < min) {
      throw new RangeError("INVALID_RANDOM_INTEGER_RANGE");
    }
    const span = max - min + 1;
    if (span > UINT32_RANGE) throw new RangeError("RANDOM_INTEGER_RANGE_TOO_WIDE");

    // Rejection sampling avoids modulo bias for ranges that do not divide 2^32.
    const limit = Math.floor(UINT32_RANGE / span) * span;
    let value;
    do {
      value = nextUint32();
    } while (value >= limit);
    return min + (value % span);
  }

  return Object.freeze({ nextUint32, nextFloat, nextInt });
}
